begin;
create table public.plantillas_correo(id_plantilla bigint generated by default as identity primary key,tipo text unique not null check(tipo in ('GENERAL','ALERTA','PEDIDO','EVENTO')),marca varchar(80) not null default 'NexoFarma',lema varchar(150) not null default 'Salud y bienestar, cerca de ti.',color_principal varchar(7) not null default '#225e4e' check(color_principal ~ '^#[0-9a-fA-F]{6}$'),color_fondo varchar(7) not null default '#f0f4ee' check(color_fondo ~ '^#[0-9a-fA-F]{6}$'),color_alerta varchar(7) not null default '#b23d36' check(color_alerta ~ '^#[0-9a-fA-F]{6}$'),introduccion varchar(500) not null default '',pie varchar(500) not null default 'Mensaje automático de la farmacia.',fuente text not null default 'Arial' check(fuente in ('Arial','Georgia')));
insert into public.plantillas_correo(tipo) values('GENERAL'),('ALERTA'),('PEDIDO'),('EVENTO');
alter table public.plantillas_correo enable row level security;
grant select,update on public.plantillas_correo to authenticated;
grant all on public.plantillas_correo to service_role;
create policy administrar on public.plantillas_correo for all to authenticated using(privado.permitido(array['ADMIN'])) with check(privado.permitido(array['ADMIN']));
create trigger historial after update on public.plantillas_correo for each row execute function privado.auditar('id_plantilla');
alter table public.eventos add column cupo integer not null default 30 check(cupo between 1 and 10000),add column recordatorio_horas integer not null default 24 check(recordatorio_horas between 1 and 168);
create table public.inscripciones(id_inscripcion bigint generated by default as identity primary key,id_evento bigint not null references public.eventos,nombre varchar(150) not null,email varchar(150) not null,telefono varchar(30),estado text not null default 'PENDIENTE' check(estado in ('PENDIENTE','CONFIRMADA','CANCELADA')),token_hash text unique not null,expira_en timestamptz not null default now()+interval '2 hours',creado_en timestamptz not null default now(),unique(id_evento,email));
alter table public.inscripciones enable row level security;
grant select on public.inscripciones to authenticated;
grant all on public.inscripciones to service_role;
grant usage,select on sequence public.inscripciones_id_inscripcion_seq to service_role;
create policy personal on public.inscripciones for select to authenticated using(privado.permitido(array['ADMIN']));
create trigger historial after insert or update on public.inscripciones for each row execute function privado.auditar('id_inscripcion');
create table privado.correos_eventos(id bigint generated by default as identity primary key,id_inscripcion bigint references public.inscripciones,clave text unique not null,destino text not null,evento text not null,cuerpo text not null,action_url text,estado text not null default 'PENDIENTE',intentos integer not null default 0,proximo_intento timestamptz not null default now());
revoke all on privado.correos_eventos from public,anon,authenticated;
create function public.inscribir_evento(p_evento bigint,p_nombre text,p_email text,p_telefono text,p_hash text,p_url text) returns void language plpgsql security definer set search_path=pg_catalog,public as $$
declare ev public.eventos;ins public.inscripciones;n integer;
begin
 select * into ev from public.eventos where id_evento=p_evento and publicado for update;
 if not found or ev.inicio<=now() then raise exception 'La actividad no admite inscripciones' using errcode='P0001';end if;
 select * into ins from public.inscripciones where id_evento=p_evento and email=lower(trim(p_email));
 if found and (ins.estado='CONFIRMADA' or (ins.estado='PENDIENTE' and ins.expira_en>now())) then return;end if;
 select count(*) into n from public.inscripciones where id_evento=p_evento and (estado='CONFIRMADA' or (estado='PENDIENTE' and expira_en>now()));
 if n>=ev.cupo then raise exception 'La actividad no tiene cupos disponibles' using errcode='P0001';end if;
 insert into public.inscripciones(id_evento,nombre,email,telefono,token_hash) values(p_evento,p_nombre,lower(trim(p_email)),p_telefono,p_hash) on conflict(id_evento,email) do update set nombre=excluded.nombre,telefono=excluded.telefono,token_hash=excluded.token_hash,estado='PENDIENTE',expira_en=now()+interval '2 hours' returning * into ins;
 insert into privado.correos_eventos(id_inscripcion,clave,destino,evento,cuerpo,action_url) values(ins.id_inscripcion,'CONFIRMAR-'||ins.id_inscripcion||'-'||p_hash,ins.email,'CONFIRMAR_INSCRIPCION','Hola '||p_nombre||'. Confirma tu inscripción a '||ev.titulo||'. El enlace vence en dos horas.',p_url);
end $$;
create function public.confirmar_inscripcion(p_hash text,p_cancelar boolean default false) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare ins public.inscripciones;ev public.eventos;
begin
 select e.* into ev from public.eventos e join public.inscripciones i using(id_evento) where i.token_hash=p_hash for update of e;
 select * into ins from public.inscripciones where token_hash=p_hash for update;
 if not found then raise exception 'Código de inscripción no encontrado' using errcode='P0002';end if;
 if p_cancelar then
  if ev.inicio<=now() then raise exception 'La actividad ya comenzó; contacta a la sucursal' using errcode='P0001';end if;
  update public.inscripciones set estado='CANCELADA' where id_inscripcion=ins.id_inscripcion;
 else
  if ins.estado='CANCELADA' or (ins.estado='PENDIENTE' and ins.expira_en<now()) or not ev.publicado or ev.inicio<=now() then raise exception 'La inscripción venció o no está disponible' using errcode='P0001';end if;
  if ins.estado='PENDIENTE' then
   if (select count(*) from public.inscripciones where id_evento=ev.id_evento and estado='CONFIRMADA')>=ev.cupo then raise exception 'La actividad no tiene cupos' using errcode='P0001';end if;
   update public.inscripciones set estado='CONFIRMADA' where id_inscripcion=ins.id_inscripcion;
   insert into privado.correos_eventos(id_inscripcion,clave,destino,evento,cuerpo) values(ins.id_inscripcion,'INSCRITO-'||ins.id_inscripcion||'-'||p_hash,ins.email,'INSCRIPCION_CONFIRMADA','Tu lugar en '||ev.titulo||' está confirmado. Fecha: '||to_char(ev.inicio at time zone 'America/Guatemala','DD/MM/YYYY HH24:MI')||' (Guatemala).') on conflict(clave) do nothing;
  end if;
 end if;
 return jsonb_build_object('estado',case when p_cancelar then 'CANCELADA' else 'CONFIRMADA' end,'titulo',ev.titulo,'inicio',ev.inicio);
end $$;
create function public.encolar_recordatorios_eventos() returns integer language plpgsql security definer set search_path=pg_catalog,public as $$
declare n integer;
begin
 insert into privado.correos_eventos(id_inscripcion,clave,destino,evento,cuerpo)
 select i.id_inscripcion,'RECORDATORIO-'||i.id_inscripcion||'-'||e.inicio::text,i.email,'RECORDATORIO_EVENTO','Te esperamos en '||e.titulo||', el '||to_char(e.inicio at time zone 'America/Guatemala','DD/MM/YYYY HH24:MI')||' (Guatemala), en '||s.nombre||'. '||s.direccion
 from public.inscripciones i join public.eventos e using(id_evento) join public.sucursales s using(id_sucursal) where i.estado='CONFIRMADA' and e.publicado and e.inicio>now() and e.inicio<=now()+make_interval(hours=>e.recordatorio_horas)
 on conflict(clave) do nothing;get diagnostics n=row_count;return n;
end $$;
revoke all on function public.inscribir_evento(bigint,text,text,text,text,text),public.confirmar_inscripcion(text,boolean),public.encolar_recordatorios_eventos() from public,anon,authenticated;
grant execute on function public.inscribir_evento(bigint,text,text,text,text,text),public.confirmar_inscripcion(text,boolean),public.encolar_recordatorios_eventos() to service_role;
do $$ declare d text;begin
 d:=pg_get_functiondef('public.tomar_correos(text)'::regprocedure);
 d:=replace(d,'end if;return resultado;', 'end if;
 for r in with pendientes as(select c.id from privado.correos_eventos c join public.inscripciones i using(id_inscripcion) join public.eventos e using(id_evento) where c.intentos<5 and c.estado in (''PENDIENTE'',''ENVIANDO'') and c.proximo_intento<=now() and e.publicado and e.inicio>now() and ((c.evento=''CONFIRMAR_INSCRIPCION'' and i.estado=''PENDIENTE'' and i.expira_en>now()) or (c.evento<>''CONFIRMAR_INSCRIPCION'' and i.estado=''CONFIRMADA'')) and (c.evento<>''RECORDATORIO_EVENTO'' or c.clave=''RECORDATORIO-''||i.id_inscripcion||''-''||e.inicio::text) order by c.id for update of c skip locked limit 10)
 update privado.correos_eventos c set estado=''ENVIANDO'',intentos=intentos+1,proximo_intento=now()+interval ''5 minutes'' from pendientes p where c.id=p.id returning c.* loop
 resultado:=resultado||jsonb_build_array(jsonb_build_object(''tipo'',''EVENTO'',''id'',r.id,''destino'',r.destino,''evento'',r.evento,''mensaje'',r.cuerpo,''action_url'',r.action_url));end loop;
 return resultado;');execute d;
 d:=pg_get_functiondef('public.cerrar_correo(text,bigint,boolean)'::regprocedure);
 d:=replace(d,'end if;', 'elsif p_tipo=''EVENTO'' then update privado.correos_eventos set estado=case when p_ok then ''ENVIADO'' when intentos>=5 then ''ERROR'' else ''PENDIENTE'' end,proximo_intento=now()+interval ''15 minutes'' where id=p_id and estado=''ENVIANDO'';end if;');execute d;
end $$;
alter table public.plantillas_correo alter column introduccion drop not null;
commit;
